#include <iostream>#include <string>using namespace std;class Person {public:    string name;    int id;    string phone;    Person(string n, int i, string p) {        name = n;        id = i;        phone = p;    }};class Student : virtual public Person {public:    string programme;    float cgpa;    Student(string n, int i, string p, string pr, float c)        : Person(n, i, p) {        programme = pr;        cgpa = c;    }};class Staff : virtual public Person {public:    string department;    double salary;    Staff(string n, int i, string p, string d, double s)        : Person(n, i, p) {        department = d;        salary = s;    }};class TeachingAssistant : public Student, public Staff {public:    TeachingAssistant(string n, int i, string p, string pr,                      float c, string d, double s)        : Person(n, i, p),          Student(n, i, p, pr, c),          Staff(n, i, p, d, s) {}};class ResearchScholar : public Student {public:    double fellowship;    ResearchScholar(string n, int i, string p, string pr,                    float c, double f)        : Person(n, i, p), Student(n, i, p, pr, c) {        fellowship = f;    }};int main() {    TeachingAssistant t("Kavya", 101, "9876543210",                        "CSE", 8.5, "Computer", 30000);    cout << "Name: " << t.name << endl;    cout << "ID: " << t.id << endl;    cout << "Programme: " << t.programme << endl;    cout << "CGPA: " << t.cgpa << endl;    cout << "Department: " << t.department << endl;    cout << "Salary: " << t.salary << endl;    return 0;}